const ef = $('Edit Fields').first().json;
const pin = String(ef.pin ?? '').trim();
const action = String(ef.action || '').toLowerCase();
const confirmed = String(ef.confirm || '') === '1';
const allRows = $input.all().map(i => i.json);

// Everybody identifies with their PIN; a QR code only opens the clock. The
// per-person codes already printed still lead here, but the employee_id they
// carry no longer picks anybody -- a card left on a desk, or a photo of one,
// would otherwise clock its owner in or out for whoever scanned it. Any scan
// without a PIN, old card or shared code, asks for one.
if (!pin) {
  return [{ json: { operation: 'ask_pin' } }];
}

// The roster comes from the Employees tab, not a literal in this file. A
// hardcoded map meant a leaver kept clocking in and a new hire could not.
// A PIN that matches nobody active is refused outright -- writing
// 'Unknown (003)' into a payroll sheet looks like a real shift and gets paid.
const roster = $('Get Roster').all().map((i) => i.json);
// A PIN may start with 0. The roster workflow stores PINs as text, but one
// typed straight into the sheet as 0482 is kept by Sheets as the number 482,
// so a short stored value is read back padded. A blank cell stays blank and
// can never match.
function storedPin(v) {
  const s = String(v ?? '').trim();
  return /^\d{1,4}$/.test(s) ? s.padStart(4, '0') : '';
}
// A PIN two people share opens neither account: either could otherwise clock
// the other in or out, and the sheet would file it under one name with no sign
// anything was wrong.
function findByPin(p) {
  if (!/^\d{4}$/.test(p)) return null;
  const owners = roster.filter((r) => storedPin(r.pin) === p);
  return owners.length === 1 ? owners[0] : null;
}
const person = findByPin(pin);

// A blank 'active' cell means active. Reading a missing column as "not
// active" would take the whole team off the clock; only an explicit no does.
const INACTIVE = ['false', 'no', 'n', '0', 'inactive', 'left'];
const isActive = person && !INACTIVE.includes(String(person.active ?? '').trim().toLowerCase());

if (!person || !isActive) {
  // Same answer for a wrong PIN, a leaver's and a shared one, so the page
  // tells somebody guessing nothing about which they hit.
  return [{ json: { operation: 'unknown_employee', display_employee: '', display_via_pin: true } }];
}
const empId = String(person.employee_id || '').trim().padStart(3, '0');
const employeeName = String(person.name || '').trim() || empId;

// The confirm taps resolve the person again from scratch, so they carry the
// PIN -- one changed between the two taps is refused, not quietly honoured.
const ident = 'pin=' + pin;

const now = DateTime.now().setZone('Asia/Manila');
const dateStr = now.toFormat('MM/dd/yyyy');
const timeStr = now.toFormat('h:mm a');

// What a full shift looks like from here. Shown on the clock-in screen so
// nobody has to work out their own finish time. Advisory only -- pay is
// whatever the clock says, so leaving earlier or later still pays honestly.
const TARGET_HOURS = 5;
const targetOutStr = now.plus({ hours: TARGET_HOURS }).toFormat('h:mm a');

function formatDuration(totalHours) {
  if (totalHours < 1) {
    const minutes = Math.max(0, Math.round(totalHours * 60));
    return minutes + (minutes === 1 ? ' minute' : ' minutes');
  }
  return totalHours.toFixed(2) + ' hours';
}

// An open row from a previous day is a forgotten clock-out, not a shift
// in progress. The two need different answers, and telling them apart
// needs the row's date rather than just its presence.
function openedToday(rowDate) {
  const d = parseInDt(rowDate, '12:00 AM');
  return d ? d.toFormat('MM/dd/yyyy') === dateStr : String(rowDate).trim() === dateStr;
}

function findOpenRows() {
  return allRows.filter(r =>
    r && r.Employee === employeeName &&
    r.Time_in && String(r.Time_in).trim() !== '' &&
    (!r.Time_out || r.Time_out === '' || r.Time_out === null)
  );
}

// Evening / night-themed verse pool (modern English, public-domain references)
const VERSES = {
  in_early: [
    { text: 'Whatever your hand finds to do, do it with all your strength.', ref: 'Ecclesiastes 9:10', meaning: 'You arrived early. Use the time well.' },
    { text: 'Trust in the Lord with all your heart, and do not rely on your own understanding.', ref: 'Proverbs 3:5', meaning: 'Settle in with trust before the night begins.' },
    { text: 'I lift up my eyes to the hills, where does my help come from?', ref: 'Psalm 121:1', meaning: 'Strength for tonight comes from above.' },
    { text: 'Commit your work to the Lord, and your plans will succeed.', ref: 'Proverbs 16:3', meaning: 'Offer your evening shift to God and your plans will hold.' }
  ],
  in_ontime: [
    { text: 'There is a time for everything, and a season for every activity under the heavens.', ref: 'Ecclesiastes 3:1', meaning: 'Right on time. Work has its hour, and this is yours.' },
    { text: 'When you lie down you will not be afraid; your sleep will be sweet.', ref: 'Proverbs 3:24', meaning: 'A faithful start now means peaceful sleep later.' },
    { text: 'The end of a thing is better than its beginning.', ref: 'Ecclesiastes 7:8', meaning: 'You have started well; the finish will be even better.' },
    { text: 'Praise the Lord, all you servants of the Lord who minister by night.', ref: 'Psalm 134:1', meaning: 'Working through the evening is an honored service.' }
  ],
  in_late: [
    { text: 'Go to the ant, you who are lazy. Watch how she works, and learn from her.', ref: 'Proverbs 6:6', meaning: 'Even small creatures show up on time. Let tomorrow look different.' },
    { text: 'Do you see someone skilled in their work? They will serve before kings.', ref: 'Proverbs 22:29', meaning: 'Diligence opens doors. Tomorrow is a chance to begin again.' },
    { text: 'Make the most of every opportunity, because the days are evil.', ref: 'Ephesians 5:16', meaning: 'Time matters. Use it well, starting now.' },
    { text: 'The lazy one does not plow in season, so at harvest time there is nothing.', ref: 'Proverbs 20:4', meaning: 'Putting things off has a cost later. Show up on time tomorrow.' }
  ],
  out_early: [
    { text: 'Whatever you do, work at it with all your heart, as working for the Lord.', ref: 'Colossians 3:23', meaning: "Make sure tonight's work was given your full heart." },
    { text: 'The Lord will watch over your coming and going both now and forevermore.', ref: 'Psalm 121:8', meaning: 'Go safely. God watches your steps as you leave.' },
    { text: 'Stand firm. Let nothing move you. Always give yourself fully to good work.', ref: '1 Corinthians 15:58', meaning: 'Steady, faithful effort is never wasted.' },
    { text: 'Let your light shine before others, so they may see your good works.', ref: 'Matthew 5:16', meaning: 'Your effort speaks. Let it shine in everything you do.' }
  ],
  out_ontime: [
    { text: 'In peace I will lie down and sleep, for you alone, Lord, make me dwell in safety.', ref: 'Psalm 4:8', meaning: 'Shift complete. Rest well tonight.' },
    { text: 'I have fought the good fight, I have finished the race, I have kept the faith.', ref: '2 Timothy 4:7', meaning: 'You finished what you set out to do. Well done.' },
    { text: 'Come to me, all who are weary and burdened, and I will give you rest.', ref: 'Matthew 11:28', meaning: "Your shift is over. Take the rest you've earned." },
    { text: 'The worker deserves their wages.', ref: 'Luke 10:7', meaning: 'Honest work is worth honest pay. You earned this.' }
  ],
  out_late: [
    { text: 'He gives strength to the weary and increases the power of the weak.', ref: 'Isaiah 40:29', meaning: 'Long night. Strength to keep going comes from God.' },
    { text: 'Let us not grow tired of doing good, in time we will reap a harvest if we do not give up.', ref: 'Galatians 6:9', meaning: 'Extra effort tonight bears fruit tomorrow.' },
    { text: 'I have learned to be content in any situation.', ref: 'Philippians 4:11', meaning: 'Long shifts and short, both belong to God. Be at peace.' },
    { text: 'He gives sleep to those he loves.', ref: 'Psalm 127:2', meaning: 'Rest is coming. Hold on a little longer.' },
    { text: 'Even at night my heart instructs me.', ref: 'Psalm 16:7', meaning: 'Late nights teach what daylight cannot.' }
  ]
};

function pickVerse(pool) {
  return pool[Math.floor(Math.random() * pool.length)];
}

function fmtMins(mins) {
  const total = Math.abs(mins);
  if (total < 60) return total + ' MIN';
  const hr = Math.floor(total / 60);
  const rest = total % 60;
  if (rest === 0) return hr + (hr === 1 ? ' HR' : ' HRS');
  return hr + (hr === 1 ? ' HR ' : ' HRS ') + rest + ' MIN';
}

// PM-shift IN bucketing. Every clock-in lands in one of these — a scan
// outside the usual window is just early or very late, never a separate
// category, so its hours are always recorded like any other shift.
function classifyIn(dt) {
  const h = dt.hour, m = dt.minute;
  if (h === 18 && m <= 5) return 'in_ontime';            // 6:00–6:05 PM
  if (h === 18 && m >= 6) return 'in_late';              // 6:06–6:59 PM
  if (h === 19 && m === 0) return 'in_late';             // 7:00 PM (inclusive)
  if (h >= 19 && h <= 23) return 'in_brutally_late';     // 7:01–11:59 PM
  return 'in_early';                                      // midnight–5:59 PM
}

// OUT bucketing. Post-midnight (h < 12) = overtime; 10:30–11:59 PM = on time; else = early.
function classifyOut(dt) {
  const h = dt.hour, m = dt.minute;
  if ((h === 22 && m >= 30) || h === 23) return 'out_ontime';
  if (h >= 0 && h < 12) return 'out_overtime';
  return 'out_early';
}

function buildInStatus(shiftType, dt) {
  const tm = dt.hour * 60 + dt.minute;
  if (shiftType === 'in_early') {
    // Hours are flexible against a five-hour target: starting early and
    // finishing early is a normal day, not something to flag. This briefly
    // showed an amber "VERY EARLY" warning, which told someone working
    // exactly as intended that they had done something wrong.
    return { label: 'STARTED EARLY', cls: 'status-info' };
  }
  if (shiftType === 'in_ontime') return { label: 'ON TIME', cls: 'status-good' };
  if (shiftType === 'in_late') {
    return { label: fmtMins(tm - 18*60) + ' LATE', cls: 'status-bad' };
  }
  return { label: 'BRUTALLY LATE (' + fmtMins(tm - 18*60) + ' PAST SHIFT)', cls: 'status-bad' };
}

function buildOutStatus(outShiftCategory, dt) {
  const ob = classifyOut(dt);
  const tm = dt.hour * 60 + dt.minute;
  if (ob === 'out_early') {
    const diff = (22*60 + 30) - tm;
    return { label: 'EARLY OUT (' + fmtMins(diff) + ' BEFORE)', cls: 'status-info' };
  }
  if (ob === 'out_ontime') return { label: 'ON TIME', cls: 'status-good' };
  // overtime — minutes past 11:00 PM. Post-midnight = 60 + tm; else = tm - 23*60.
  let diff;
  if (dt.hour < 12) diff = 60 + tm;
  else diff = tm - 23*60;
  return { label: 'OVERTIME (+' + fmtMins(diff) + ')', cls: 'status-warn' };
}

function inBadge(shiftType) {
  if (shiftType === 'in_brutally_late') return { label: 'Brutally Late In', cls: 'badge-err' };
  return { label: 'Clock In', cls: 'badge-in' };
}

function outBadge(outShiftCategory) {
  if (outShiftCategory === 'brutally_late') return { label: 'Brutally Late Out', cls: 'badge-err' };
  return { label: 'Clock Out', cls: 'badge-out' };
}

function inSubtitle(shiftType) {
  if (shiftType === 'in_brutally_late') return 'You are well past shift start. Show up on time tomorrow.';
  return 'Your scan was recorded.';
}

function outSubtitle(outShiftCategory) {
  if (outShiftCategory === 'brutally_late') return 'Late in, recorded out. Show up on time tomorrow.';
  return 'Your scan was recorded.';
}

function roundMin(mins) {
  // round to nearest hour; round up when within 20 min of the next hour (>=40 min in)
  const base = Math.floor(mins / 60);
  return (mins % 60) >= 40 ? base + 1 : base;
}
// A row left open longer than this is a forgotten clock-out, not somebody
// still working. A 2:26 AM scan closed at 4:58 PM once wrote 14 hours nobody
// worked, and there was no signal until payroll.
const STALE_SHIFT_HOURS = 12;

function computeTotalHours(inDt, outDt) {
  // Every hour on the clock is paid. No fixed shift length, no window and no
  // cap — the total is simply clock-out minus clock-in, rounded to the hour.
  const workedMin = Math.max(0, Math.round(outDt.diff(inDt, 'minutes').minutes));
  return roundMin(workedMin);
}

function hoursLabel(h) {
  return h + (h === 1 ? ' hour' : ' hours');
}

function parseInDt(dateStr, timeStr) {
  const formats = ['yyyy-MM-dd h:mm:ss a', 'MM/dd/yyyy h:mm:ss a', 'M/d/yyyy h:mm:ss a', 'yyyy-MM-dd h:mm a', 'MM/dd/yyyy h:mm a', 'M/d/yyyy h:mm a', 'yyyy-MM-dd HH:mm:ss', 'MM/dd/yyyy HH:mm:ss', 'yyyy-MM-dd HH:mm', 'MM/dd/yyyy HH:mm'];
  for (const fmt of formats) {
    const dt = DateTime.fromFormat(String(dateStr) + ' ' + String(timeStr), fmt, { zone: 'Asia/Manila' });
    if (dt.isValid) return dt;
  }
  return null;
}

// Nothing is recorded without a tap. A code that punches the moment it
// loads means anything which merely fetches the link -- a crawler, a chat
// app's link preview, a restored browser tab -- records a shift. Google
// did exactly that three times in seven seconds one night, and the
// phantom row locked out the next real scan for fourteen hours.
//
// It also removes the second failure: there is one code now, and the
// direction is chosen by tapping rather than by which card was picked up.
if (!confirmed) {
  const openNow = findOpenRows();
  // Only today's open row means 'you are clocked in'. A row left open
  // yesterday must not turn today's scan into a clock-out -- that is what
  // walked someone into closing the wrong day.
  if (openNow.length > 0 && openedToday(openNow[openNow.length - 1].Date)) {
    const row = openNow[openNow.length - 1];
    const inDt = parseInDt(row.Date, row.Time_in);
    const mins = inDt ? Math.max(0, Math.round(now.diff(inDt, 'minutes').minutes)) : 0;
    return [{ json: {
      operation: 'choose',
      choose_mode: 'out',
      display_employee: employeeName,
      display_employee_id: empId,
      display_ident: ident,
      display_time_in: row.Time_in,
      display_elapsed: fmtMins(mins),
      display_target: inDt ? inDt.plus({ hours: TARGET_HOURS }).toFormat('h:mm a') : ''
    } }];
  }
  const forgotten = openNow.length > 0 ? openNow[openNow.length - 1] : null;
  return [{ json: {
    operation: 'choose',
    choose_mode: 'in',
    // Named, not touched. Fixing it is a decision for the sheet, not
    // something to do to a payroll row on someone's way through a door.
    display_stale: forgotten
      ? forgotten.Date + ' was left open at ' + forgotten.Time_in
      : '',
    display_employee: employeeName,
    display_employee_id: empId,
    display_ident: ident,
    display_time: timeStr,
    display_target: targetOutStr
  } }];
}

if (action === 'in') {
  const openRows = findOpenRows();
  // Clocking in clocks you in. Yesterday's unclosed row is left exactly as
  // it is -- it gets fixed in the sheet, not by refusing today's shift.
  if (openRows.length > 0 && openedToday(openRows[openRows.length - 1].Date)) {
    const openRow = openRows[openRows.length - 1];
    return [{ json: {
      operation: 'no_clock_out',
      display_employee: employeeName,
      display_date: openRow.Date,
      display_time_in: openRow.Time_in
    } }];
  }
  const shiftType = classifyIn(now);
  let pool;
  if (shiftType === 'in_early') pool = VERSES.in_early;
  else if (shiftType === 'in_ontime') pool = VERSES.in_ontime;
  else pool = VERSES.in_late;
  const v = pickVerse(pool);
  const s = buildInStatus(shiftType, now);
  const b = inBadge(shiftType);
  return [{ json: {
    operation: 'append',
    Date: dateStr,
    Employee: employeeName,
    Time_in: timeStr,
    Time_out: '',
    Total_hours: '',
    display_employee: employeeName,
    display_time: timeStr,
    display_target_time: targetOutStr,
    display_badge_label: b.label,
    display_badge_class: b.cls,
    display_subtitle: inSubtitle(shiftType),
    display_status_label: s.label,
    display_status_class: s.cls,
    display_verse_text: v.text,
    display_verse_ref: v.ref,
    display_verse_meaning: v.meaning,
    display_shift_type: shiftType
  } }];
}

if (action === 'out') {
  const open = findOpenRows();
  if (open.length === 0) {
    return [{ json: { operation: 'no_clock_in', display_employee: employeeName } }];
  }
  const row = open[open.length - 1];
  const inDt = parseInDt(row.Date, row.Time_in);
  if (!inDt) {
    return [{ json: { operation: 'no_clock_in', display_employee: employeeName } }];
  }
  const inShift = classifyIn(inDt);
  const outBucket = classifyOut(now);

  const outCat = inShift === 'in_brutally_late' ? 'brutally_late' : 'regular';

  // Refuse to invent a total for an implausible span. The row still closes —
  // otherwise the next person stays locked out — but Total_hours is left
  // blank so the dashboard flags it rather than paying a number nobody
  // worked. Guessing the real clock-out time would be worse than blank.
  const workedMin = Math.max(0, Math.round(now.diff(inDt, 'minutes').minutes));
  const stale = workedMin > STALE_SHIFT_HOURS * 60;
  const totalHours = stale ? '' : computeTotalHours(inDt, now);

  let pool;
  if (outCat === 'brutally_late') pool = VERSES.out_late;
  else if (outBucket === 'out_early') pool = VERSES.out_early;
  else if (outBucket === 'out_ontime') pool = VERSES.out_ontime;
  else pool = VERSES.out_late;
  const v = pickVerse(pool);

  const s = stale
    ? { label: 'SHIFT LEFT OPEN — TOTAL NOT SET', cls: 'status-warn' }
    : buildOutStatus(outCat, now);
  const b = outBadge(outCat);

  return [{ json: {
    operation: 'update',
    row_number: row.row_number,
    Date: row.Date,
    Employee: employeeName,
    Time_out: timeStr,
    Total_hours: totalHours,
    display_employee: employeeName,
    display_time: timeStr,
    display_total: stale ? 'Needs checking' : hoursLabel(totalHours),
    display_total_label: stale ? 'Left Open Since ' + row.Time_in : 'Total Time',
    display_badge_label: b.label,
    display_badge_class: b.cls,
    display_subtitle: outSubtitle(outCat),
    display_status_label: s.label,
    display_status_class: s.cls,
    display_verse_text: v.text,
    display_verse_ref: v.ref,
    display_verse_meaning: v.meaning,
    display_shift_type: outCat
  } }];
}

return [{ json: { operation: 'no_clock_in', display_employee: 'Unknown' } }];

const SHEET_ID = 1545975491;                 // pivot tab "Sheet2"
const DATE_COL = 0;

// Columns are found by their headers, not listed here. A name list in this
// node meant everyone added after it was written -- Jeremy, then whoever
// next -- was silently left out of the pivot. Row 1 carries each person's
// name over their In/Out pair; row 2 carries "In", "Out" and
// "Total Hours of <name>".
const HEADER_NAME_ROW = 0;
const HEADER_LABEL_ROW = 1;

// Normalize any supported date string to zero-padded MM/DD/YYYY, else null.
function normDate(s) {
  const t = String(s == null ? '' : s).trim();
  let m = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return m[1].padStart(2, '0') + '/' + m[2].padStart(2, '0') + '/' + m[3];
  m = t.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return m[2].padStart(2, '0') + '/' + m[3].padStart(2, '0') + '/' + m[1];
  return null;
}

const norm = (v) => String(v == null ? '' : v).trim().toLowerCase();

function cell(rowIndex, colIndex, value, kind) {
  const userEnteredValue = kind === 'number'
    ? { numberValue: Number(value) }
    : { stringValue: String(value) };
  return {
    updateCells: {
      range: {
        sheetId: SHEET_ID,
        startRowIndex: rowIndex, endRowIndex: rowIndex + 1,
        startColumnIndex: colIndex, endColumnIndex: colIndex + 1,
      },
      rows: [{ values: [{ userEnteredValue }] }],
      fields: 'userEnteredValue',
    },
  };
}

function gridRange(r0, r1, c0, c1) {
  return { sheetId: SHEET_ID, startRowIndex: r0, endRowIndex: r1, startColumnIndex: c0, endColumnIndex: c1 };
}

function has(v) { return v !== undefined && v !== null && v !== ''; }

// Where a person's three columns are, or null for any that is missing.
function findColumns(name, nameRow, labelRow) {
  const want = norm(name);
  let pair = -1;
  for (let c = 1; c < nameRow.length; c++) {
    if (norm(nameRow[c]) === want && norm(labelRow[c]) === 'in' && norm(labelRow[c + 1]) === 'out') {
      pair = c;
      break;
    }
  }
  let total = -1;
  for (let c = 1; c < labelRow.length; c++) {
    if (norm(labelRow[c]) === 'total hours of ' + want) { total = c; break; }
  }
  return { in: pair === -1 ? null : pair, out: pair === -1 ? null : pair + 1, total: total === -1 ? null : total };
}

// Somebody with no columns gets them on their first scan, appended past the
// last used column. Appending rather than inserting beside the others is the
// point: nothing existing moves, so no historical cell and no hand-written
// formula in this tab ever shifts under anybody.
function provision(name, cols, firstFreeCol) {
  const requests = [];
  let next = firstFreeCol;
  const width = (cols.in === null ? 2 : 0) + (cols.total === null ? 1 : 0);
  // Room at the grid's edge. Costs a few empty columns once per new person;
  // writing past the edge would fail the whole batch, and with it the scan's
  // pivot write, on every scan until somebody noticed.
  requests.push({ appendDimension: { sheetId: SHEET_ID, dimension: 'COLUMNS', length: width } });

  if (cols.in === null) {
    // Look like the existing pairs: borrow Ivan's header formatting (B1:C2).
    requests.push({ copyPaste: {
      source: gridRange(0, 2, 1, 3),
      destination: gridRange(0, 2, next, next + 2),
      pasteType: 'PASTE_FORMAT',
    } });
    requests.push(cell(HEADER_NAME_ROW, next, name, 'string'));
    requests.push(cell(HEADER_LABEL_ROW, next, 'In', 'string'));
    requests.push(cell(HEADER_LABEL_ROW, next + 1, 'Out', 'string'));
    cols = { ...cols, in: next, out: next + 1 };
    next += 2;
  }
  if (cols.total === null) {
    requests.push(cell(HEADER_LABEL_ROW, next, 'Total Hours of ' + name, 'string'));
    cols = { ...cols, total: next };
    next += 1;
  }
  return { requests, cols };
}

// decideItems: the canonical clock event(s) from the Decide node.
// colA: pivot column A values (index 0 = sheet row 1), used to find the row.
// header: rows 1 and 2 of the pivot, used to find (or make) the columns.
function buildPivotItems(decideItems, colA, header) {
  // Map normalized date -> 0-based row index; track the last dated row.
  const dateToRow = new Map();
  let lastDatedRow = -1;
  for (let i = 0; i < colA.length; i++) {
    const nd = normDate(colA[i]);
    if (nd) {
      if (!dateToRow.has(nd)) dateToRow.set(nd, i);
      lastDatedRow = i;
    }
  }
  const nameRow = header[HEADER_NAME_ROW] || [];
  const labelRow = header[HEADER_LABEL_ROW] || [];
  // No dates, or no header, => treat as a failed/empty read and skip, so we
  // never append duplicate rows or columns when the lookup is unavailable.
  if (dateToRow.size === 0 || norm(labelRow[DATE_COL]) !== 'date') return [];

  let firstFreeCol = Math.max(nameRow.length, labelRow.length);

  const out = [];
  for (const item of decideItems) {
    const j = item.json;
    const name = String(j.display_employee || j.Employee || '').trim();
    if (!name) continue;
    const nd = normDate(j.Date);
    if (!nd) continue;

    const requests = [];
    let cols = findColumns(name, nameRow, labelRow);
    if (cols.in === null || cols.total === null) {
      const made = provision(name, cols, firstFreeCol);
      requests.push(...made.requests);
      cols = made.cols;
      firstFreeCol = Math.max(firstFreeCol, (cols.total ?? 0) + 1, (cols.out ?? 0) + 1);
    }

    let rowIndex;
    let isNewRow = false;
    if (dateToRow.has(nd)) {
      rowIndex = dateToRow.get(nd);
    } else {
      rowIndex = lastDatedRow + 1;             // append just after the last date
      isNewRow = true;
    }

    if (isNewRow) requests.push(cell(rowIndex, DATE_COL, nd, 'string'));
    if (j.operation === 'append') {
      if (has(j.Time_in)) requests.push(cell(rowIndex, cols.in, j.Time_in, 'string'));
    } else if (j.operation === 'update') {
      if (has(j.Time_out))      requests.push(cell(rowIndex, cols.out,       j.Time_out,      'string'));
      if (has(j.Total_hours))   requests.push(cell(rowIndex, cols.total,     j.Total_hours,   'number'));
    }
    if (requests.length) out.push({ json: { body: { requests } } });
  }
  return out;
}

